@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: grid;
    width: 32rem;
    max-width: 100%;
    gap: var(--moduix-spacing-3);

    &[data-dragging],
    &[data-panning] {
      cursor: grabbing;
    }
  }

  /* Ark sets position, overflow, and touch handling inline. */
  .viewport {
    box-sizing: border-box;
    width: 100%;
    aspect-ratio: 8 / 5;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-lg);
    background: repeating-conic-gradient(
        var(--moduix-color-muted) 0 25%,
        var(--moduix-color-background) 0 50%
      )
      0 0 / 1rem 1rem;

    &[data-disabled] {
      cursor: grab;
    }
  }

  /* Ark forces object-fit: fill and measures the element box, so the box itself keeps the image
     ratio: it shrinks to fit the viewport and stays centered. */
  .image {
    position: absolute;
    inset: 0;
    display: block;
    max-width: 100%;
    max-height: 100%;
    margin: auto;
  }

  .selection {
    box-sizing: border-box;
    border: var(--moduix-border-width-md) solid var(--moduix-color-primary);
    border-radius: var(--moduix-radius-md);
    box-shadow:
      0 0 0 9999px rgb(0 0 0 / 45%),
      inset 0 0 0 var(--moduix-border-width-sm) rgb(255 255 255 / 64%);
    cursor: grab;

    &[data-shape='circle'] {
      border-color: transparent;
      border-radius: var(--moduix-radius-full);
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-offset);
    }

    &[data-dragging] {
      cursor: grabbing;
    }

    &[data-disabled] {
      cursor: default;
    }
  }

  .grid {
    &[data-axis='horizontal'] {
      border-block: var(--moduix-border-width-sm) solid rgb(255 255 255 / 62%);
    }

    &[data-axis='vertical'] {
      border-inline: var(--moduix-border-width-sm) solid rgb(255 255 255 / 62%);
    }
  }

  /* Ark positions each handle inline and sizes edge handles along the selection side. */
  .handle {
    width: var(--moduix-spacing-3);
    height: var(--moduix-spacing-3);
    border-radius: var(--moduix-radius-xs);
    background-color: rgb(255 255 255 / 96%);
    box-shadow: 0 1px 3px rgb(15 23 42 / 18%);

    &[data-position='n'],
    &[data-position='s'] {
      height: 0.2rem;
      border-radius: var(--moduix-radius-full);
    }

    &[data-position='e'],
    &[data-position='w'] {
      width: 0.2rem;
      border-radius: var(--moduix-radius-full);
    }

    &[data-position='nw'],
    &[data-position='ne'],
    &[data-position='se'],
    &[data-position='sw'] {
      z-index: 1;
    }

    &[data-disabled] {
      display: none;
    }
  }
}

import {
  ImageCropper as ArkImageCropper,
  ImageCropperContext,
  useImageCropper,
  useImageCropperContext,
} from '@ark-ui/vue/image-cropper';
import ImageCropper from './ImageCropper.vue';
import ImageCropperCropArea from './ImageCropperCropArea.vue';
import ImageCropperGrid from './ImageCropperGrid.vue';
import ImageCropperHandle from './ImageCropperHandle.vue';
import ImageCropperImage from './ImageCropperImage.vue';
import ImageCropperRootProvider from './ImageCropperRootProvider.vue';
import ImageCropperSelection from './ImageCropperSelection.vue';
import ImageCropperViewport from './ImageCropperViewport.vue';

const ImageCropperHandles = ArkImageCropper.handles;

export {
  ImageCropper,
  ImageCropperContext,
  ImageCropperCropArea,
  ImageCropperGrid,
  ImageCropperHandle,
  ImageCropperHandles,
  ImageCropperImage,
  ImageCropperRootProvider,
  ImageCropperSelection,
  ImageCropperViewport,
  useImageCropper,
  useImageCropperContext,
};

export type {
  ImageCropperContextProps,
  ImageCropperCropChangeDetails,
  ImageCropperFlipChangeDetails,
  ImageCropperFlipState,
  ImageCropperGridProps,
  ImageCropperHandlePosition,
  ImageCropperHandleProps,
  ImageCropperImageProps,
  ImageCropperRootEmits,
  ImageCropperRootProps,
  ImageCropperRootProviderProps,
  ImageCropperRotationChangeDetails,
  ImageCropperSelectionProps,
  ImageCropperViewportProps,
  ImageCropperZoomChangeDetails,
  UseImageCropperContext,
  UseImageCropperProps,
  UseImageCropperReturn,
} from '@ark-ui/vue/image-cropper';
export type { Props as ImageCropperCropAreaProps } from './ImageCropperCropArea.vue';
